-- V201 — durable fulfillment and tracking 3.0.
CREATE TABLE IF NOT EXISTS trust_shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES trust_orders(id) ON DELETE CASCADE,carrier text NOT NULL,service text NOT NULL,tracking_number text,status text NOT NULL CHECK(status IN ('PLANNED','LABEL_CREATED','PICKED_UP','IN_TRANSIT','OUT_FOR_DELIVERY','DELIVERED','EXCEPTION','CANCELLED')),warehouse_id text,destination jsonb,eta_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS idx_trust_shipments_tracking ON trust_shipments(carrier,tracking_number) WHERE tracking_number IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_trust_shipments_order ON trust_shipments(order_id,created_at ASC);CREATE INDEX IF NOT EXISTS idx_trust_shipments_status ON trust_shipments(status,updated_at DESC);
CREATE TABLE IF NOT EXISTS trust_shipment_tracking_events (id text PRIMARY KEY,shipment_id uuid NOT NULL REFERENCES trust_shipments(id) ON DELETE CASCADE,event_type text NOT NULL CHECK(event_type IN ('STATUS','EXCEPTION','ETA_UPDATE')),status text,exception_code text CHECK(exception_code IS NULL OR exception_code IN ('ADDRESS_ISSUE','CUSTOMS_HOLD','DAMAGED','RECIPIENT_UNAVAILABLE','WEATHER_DELAY','CARRIER_DELAY','UNKNOWN')),occurred_at timestamptz NOT NULL,location text,description text,eta_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_trust_shipment_events_shipment ON trust_shipment_tracking_events(shipment_id,occurred_at ASC);CREATE INDEX IF NOT EXISTS idx_trust_shipment_events_exception ON trust_shipment_tracking_events(exception_code,occurred_at DESC);
